import numpy as np
from scipy.optimize import minimize_scalar
one=np.ones_like(P)
def cols(w,extra):
    s=np.sin(w*t); c=np.cos(w*t)
    base=[one,P*np.log(P),1/P,t,t/P,s/P,c/P,s,c,t*s,t*c]
    ex={'t2':t**2,'t2/P':t**2/P,'Pt':P*t,'P':P,'s2':np.sin(2*w*t)/P,'c2':np.cos(2*w*t)/P,'sP':s*P,'cP':c*P,'tsP':t*s*P,'1/P2':1/P**2,'expt':np.exp(-t/4)}
    return np.column_stack(base+[ex[k] for k in extra])
def nm(w,extra):
    X=cols(w,extra); b=np.linalg.lstsq(X,dP_dt,rcond=None)[0]
    return np.mean((X@b-dP_dt)**2)/np.var(dP_dt), b
for extra in [[],['t2'],['t2/P'],['Pt'],['P'],['s2','c2'],['sP','cP'],['tsP'],['1/P2'],['expt'],['t2','t2/P','P','Pt']]:
    r=minimize_scalar(lambda w: nm(w,extra)[0],bounds=(0.2,0.6),method='bounded')
    print(extra, r.x, r.fun)
